# Try a new approach: find the most common non-5 color in each 3x3 block
def transform_v2(grid):
    h, w = len(grid), len(grid[0])
    result_h, result_w = h // 3, w // 3
    result = []

    for r in range(result_h):
        row_out = []
        for c in range(result_w):
            # Extract 3x3 block
            counts = {}
            for dr in range(3):
                for dc in range(3):
                    val = grid[r*3 + dr][c*3 + dc]
                    counts[val] = counts.get(val, 0) + 1

            # Find most common non-5 color
            non_5_colors = {k: v for k, v in counts.items() if k != 5}

            if non_5_colors:
                # Get max count among non-5 colors
                max_val = max(non_5_colors.values())
                # Filter colors that reach max_val
                candidates = [k for k, v in non_5_colors.items() if v == max_val]
                if len(candidates) == 1:
                    row_out.append(candidates[0])
                else:
                    row_out.append(0)
            else:
                row_out.append(0)

        result.append(row_out)

    return result

